using System;
using System.Threading;
using System.Threading.Tasks;
using Application.Waitlist;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

namespace Trale.Controllers;

/// <summary>
/// The waitlist form of the public pages <c>/learn/&lt;language&gt;/</c> (generated by <c>site/</c>). The
/// pages have no JavaScript: the form is an ordinary HTML POST, and the answer is a redirect to a
/// static page. No account, no cookie.
/// </summary>
[Route("waitlist")]
public class WaitlistController(JoinWaitlistService join, IMemoryCache cache) : Controller
{
    /// <summary>How many times a day one address of the network may send the form.</summary>
    public const int MaxPerAddressPerDay = 10;

    public const string ThanksPath = "/learn/thanks/";

    public class Form
    {
        public string? Email { get; set; }
        public string? Lang { get; set; }
        public string? Platform { get; set; }
        public string? Src { get; set; }

        /// <summary>Hidden from people and left empty by them; a script that fills every field gives itself away.</summary>
        public string? Website { get; set; }
    }

    [HttpPost]
    [Consumes("application/x-www-form-urlencoded")]
    public async Task<IActionResult> Join([FromForm] Form form, CancellationToken ct)
    {
        // A filled trap or too many tries: the same answer as a success, and nothing is written.
        if (!string.IsNullOrEmpty(form.Website) || !Allow(ClientAddress()))
        {
            return SeeOther(ThanksPath);
        }

        var result = await join.ExecuteAsync(form.Email, form.Lang, form.Platform, form.Src ?? SourceOfPage(), ct);
        if (result != JoinWaitlistResult.Invalid)
        {
            return SeeOther(ThanksPath);
        }

        // The browser checks the fields before sending, so this is a hand-made request: back to the form.
        var language = form.Lang?.Trim().ToLowerInvariant();
        return SeeOther(language != null && WaitlistOptions.Languages.Contains(language) ? $"/learn/{language}/" : "/learn/");
    }

    /// <summary>
    /// The tag of the link the person opened the page with (<c>/learn/georgian/?src=…</c>). The page has
    /// no script to copy it into the form, but the browser names the page, query included, in Referer.
    /// </summary>
    private string? SourceOfPage()
    {
        return Uri.TryCreate(Request.Headers.Referer.ToString(), UriKind.Absolute, out var page)
            ? Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(page.Query).TryGetValue("src", out var src) ? src.ToString() : null
            : null;
    }

    private IActionResult SeeOther(string path)
    {
        Response.Headers.Location = path;
        return StatusCode(303);
    }

    private string ClientAddress()
    {
        // Behind the ingress the client is the first address of X-Forwarded-For.
        var forwarded = Request.Headers["X-Forwarded-For"].ToString();
        var first = forwarded.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        return first.Length > 0 ? first[0] : HttpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown";
    }

    /// <summary>Counted in this instance's memory: with two instances the real ceiling is twice the number, which is fine for its purpose.</summary>
    private bool Allow(string address)
    {
        var key = $"waitlist:{DateTime.UtcNow:yyyyMMdd}:{address}";
        var count = cache.GetOrCreate(key, entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromDays(1);
            return new Counter();
        })!;
        return Interlocked.Increment(ref count.Value) <= MaxPerAddressPerDay;
    }

    private sealed class Counter
    {
        public int Value;
    }
}
